from pathlib import Path

path=Path("index.html")
text=path.read_text()

def replace_once(old,new,label):
    global text
    count=text.count(old)
    if count!=1:
        raise SystemExit(f"{label}: expected exactly one anchor, found {count}")
    text=text.replace(old,new,1)

